begin read only;select
 (select count(*) from public.companies where left(id::text,8)='86200000') fixture_companies,(select count(*) from public.company_settings where left(company_id::text,8)='86200000') fixture_settings,(select count(*) from public.company_memberships where left(company_id::text,8)='86200000') fixture_memberships,(select count(*) from public.projects where left(id::text,8)='86200000') fixture_projects,(select count(*) from public.parties where left(id::text,8)='86200000') fixture_parties,(select count(*) from public.subcontracts where left(id::text,8)='86200000') fixture_subcontracts,(select count(*) from public.profiles where user_id in(select id from auth.users where email='p6c-s16-browser@example.test')) browser_profile,(select count(*) from auth.users where email='p6c-s16-browser@example.test') browser_auth,(select count(*) from public.companies) companies,(select count(*) from public.company_settings) settings,(select count(*) from public.companies c left join public.company_settings s on s.company_id=c.id where s.company_id is null) missing,(select count(*) from public.company_settings s left join public.companies c on c.id=s.company_id where c.id is null) orphan;commit;
